    static let all: [DuaItem] = [
        DuaItem(id: "q01", text: "رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ ﴿١٢٧﴾", ref: "البقرة: 127", source: "القرآن الكريم — سورة البقرة: 127", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q02", text: "رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ ﴿٢٠١﴾", ref: "البقرة: 201", source: "القرآن الكريم — سورة البقرة: 201", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q03", text: "رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ ﴿٢٥٠﴾", ref: "البقرة: 250", source: "القرآن الكريم — سورة البقرة: 250", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q04", text: "رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ ﴿٢٨٦﴾", ref: "البقرة: 286", source: "القرآن الكريم — سورة البقرة: 286", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q05", text: "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ ﴿٨﴾", ref: "آل عمران: 8", source: "القرآن الكريم — سورة آل عمران: 8", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q06", text: "رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴿١٦﴾", ref: "آل عمران: 16", source: "القرآن الكريم — سورة آل عمران: 16", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q07", text: "رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ ﴿٥٣﴾", ref: "آل عمران: 53", source: "القرآن الكريم — سورة آل عمران: 53", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q08", text: "رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ ﴿١٤٧﴾", ref: "آل عمران: 147", source: "القرآن الكريم — سورة آل عمران: 147", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q09", text: "حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ ﴿١٧٣﴾", ref: "آل عمران: 173", source: "القرآن الكريم — سورة آل عمران: 173", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q10", text: "رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَـٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ ﴿١٩٣﴾ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ ﴿١٩٤﴾", ref: "آل عمران: 193–194", source: "القرآن الكريم — سورة آل عمران: 193–194", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q11", text: "رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ ﴿٢٣﴾", ref: "الأعراف: 23", source: "القرآن الكريم — سورة الأعراف: 23", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q12", text: "رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ ﴿١٢٦﴾", ref: "الأعراف: 126", source: "القرآن الكريم — سورة الأعراف: 126", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q13", text: "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّـٰلِمِينَ ﴿٨٥﴾ وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَـٰفِرِينَ ﴿٨٦﴾", ref: "يونس: 85–86", source: "القرآن الكريم — سورة يونس: 85–86", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q14", text: "رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ ﴿٤٠﴾ رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ ﴿٤١﴾", ref: "إبراهيم: 40–41", source: "القرآن الكريم — سورة إبراهيم: 40–41", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q15", text: "رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا ﴿٢٤﴾", ref: "الإسراء: 24", source: "القرآن الكريم — سورة الإسراء: 24", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q16", text: "رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَـٰنًا نَّصِيرًا ﴿٨٠﴾", ref: "الإسراء: 80", source: "القرآن الكريم — سورة الإسراء: 80", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q17", text: "رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا ﴿١٠﴾", ref: "الكهف: 10", source: "القرآن الكريم — سورة الكهف: 10", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q18", text: "رَبِّ ٱشْرَحْ لِى صَدْرِى ﴿٢٥﴾ وَيَسِّرْ لِىٓ أَمْرِى ﴿٢٦﴾ وَٱحْلُلْ عُقْدَةً مِّن لِّسَانِى ﴿٢٧﴾ يَفْقَهُوا۟ قَوْلِى ﴿٢٨﴾", ref: "طه: 25–28", source: "القرآن الكريم — سورة طه: 25–28", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q19", text: "رَّبِّ زِدْنِى عِلْمًا ﴿١١٤﴾", ref: "طه: 114", source: "القرآن الكريم — سورة طه: 114", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q20", text: "لَّآ إِلَـٰهَ إِلَّآ أَنتَ سُبْحَـٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّـٰلِمِينَ ﴿٨٧﴾", ref: "الأنبياء: 87", source: "القرآن الكريم — سورة الأنبياء: 87", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q21", text: "رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ ﴿٨٩﴾", ref: "الأنبياء: 89", source: "القرآن الكريم — سورة الأنبياء: 89", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q22", text: "رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَـٰطِينِ ﴿٩٧﴾ وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ ﴿٩٨﴾", ref: "المؤمنون: 97–98", source: "القرآن الكريم — سورة المؤمنون: 97–98", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q23", text: "رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ ﴿١١٨﴾", ref: "المؤمنون: 118", source: "القرآن الكريم — سورة المؤمنون: 118", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q24", text: "رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ﴿٦٥﴾", ref: "الفرقان: 65", source: "القرآن الكريم — سورة الفرقان: 65", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q25", text: "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا ﴿٧٤﴾", ref: "الفرقان: 74", source: "القرآن الكريم — سورة الفرقان: 74", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q26", text: "رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّـٰلِحِينَ ﴿١٩﴾", ref: "النمل: 19", source: "القرآن الكريم — سورة النمل: 19", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q27", text: "رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى ﴿١٦﴾", ref: "القصص: 16", source: "القرآن الكريم — سورة القصص: 16", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q28", text: "رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ ﴿٢٤﴾", ref: "القصص: 24", source: "القرآن الكريم — سورة القصص: 24", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q29", text: "رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ ﴿١٥﴾", ref: "الأحقاف: 15", source: "القرآن الكريم — سورة الأحقاف: 15", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q30", text: "رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَـٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ ﴿١٠﴾", ref: "الحشر: 10", source: "القرآن الكريم — سورة الحشر: 10", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q31", text: "رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ ﴿٤﴾", ref: "الممتحنة: 4", source: "القرآن الكريم — سورة الممتحنة: 4", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q32", text: "رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ ﴿٨﴾", ref: "التحريم: 8", source: "القرآن الكريم — سورة التحريم: 8", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "q33", text: "رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارًۢا ﴿٢٨﴾", ref: "نوح: 28", source: "القرآن الكريم — سورة نوح: 28", grade: "قرآن كريم — نص المصحف العثماني (Tanzil)", note: "", reward: "", count: 1, cat: "من القرآن", quran: true),
        DuaItem(id: "du-01", text: "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ", ref: "البخاري 6312", source: "البخاري 6312 و6324 (حديث حذيفة): «وإذا استيقظ قال...»", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "الاستيقاظ من النوم", quran: false),
        DuaItem(id: "du-02", text: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", ref: "البخاري 142", source: "البخاري 142 و6322، ومسلم 375 (حديث أنس): «كان إذا دخل الخلاء قال...»", grade: "صحيح — متفق عليه", note: "يقال قبل الدخول. زيادة «بسم الله» في أوله ليست في الصحيحين، فلم نثبتها.", reward: "", count: 1, cat: "دخول الخلاء", quran: false),
        DuaItem(id: "du-03", text: "غُفْرَانَكَ", ref: "أبو داود 30", source: "أبو داود 30 (حديث عائشة): «كان إذا خرج من الغائط قال: غفرانك»", grade: "صحيح — الألباني (صحيح أبي داود 30، صحيح ابن ماجه 247)؛ النووي: صحيح (الإيجاز 166)؛ شعيب الأرناؤوط: إسناده حسن", note: "", reward: "", count: 1, cat: "الخروج من الخلاء", quran: false),
        DuaItem(id: "du-04", text: "أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", ref: "مسلم 234", source: "مسلم 234 (حديث عمر بن الخطاب): «ما منكم من أحد يتوضأ فيبلغ - أو فيسبغ - الوضوء ثم يقول... إلا فتحت له أبواب الجنة الثمانية يدخل من أيها شاء»", grade: "صحيح — رواه مسلم", note: "", reward: "«إِلاَّ فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ» (مسلم 234)", count: 1, cat: "بعد الوضوء", quran: false),
        DuaItem(id: "du-06", text: "أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ", ref: "أبو داود 466", source: "أبو داود 466 (حديث عبد الله بن عمرو): «كان إذا دخل المسجد قال...»، وفيه: «فإذا قال ذلك قال الشيطان: حُفظ مني سائر اليوم»", grade: "صحيح — الألباني (صحيح أبي داود 466)؛ شعيب الأرناؤوط: إسناده صحيح (تخريج زاد المعاد 2/336) وجيد (تخريج سنن أبي داود 466)؛ ابن حجر: حسن غريب؛ ابن باز: إسناده حسن", note: "", reward: "", count: 1, cat: "دخول المسجد", quran: false),
        DuaItem(id: "du-07", text: "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", ref: "مسلم 713", source: "مسلم 713 (حديث أبي حميد أو أبي أسيد): «إذا دخل أحدكم المسجد فليقل...»", grade: "صحيح — رواه مسلم", note: "", reward: "", count: 1, cat: "دخول المسجد", quran: false),
        DuaItem(id: "du-08", text: "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ", ref: "مسلم 713", source: "مسلم 713: «وإذا خرج فليقل...»", grade: "صحيح — رواه مسلم", note: "", reward: "", count: 1, cat: "الخروج من المسجد", quran: false),
        DuaItem(id: "du-09", text: "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ", ref: "أبو داود 4020", source: "أبو داود 4020 (حديث أبي سعيد الخدري): «كان إذا استجدّ ثوبًا سمّاه باسمه... ثم يقول»", grade: "صحيح — الألباني (صحيح أبي داود 4020)؛ شعيب الأرناؤوط: حسن (تخريج سنن أبي داود 4020)", note: "يسمّي الثوب باسمه (قميصًا أو عمامة...) قبل الدعاء، كما في الحديث.", reward: "", count: 1, cat: "لبس الثوب الجديد", quran: false),
        DuaItem(id: "du-10", text: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ", ref: "البخاري 6369", source: "البخاري 6369 (حديث أنس): «كان النبي ﷺ يقول...»", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "الهم والحزن", quran: false),
        DuaItem(id: "du-11", text: "لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ، وَرَبُّ الأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيمِ", ref: "البخاري 6346", source: "البخاري 6346، ومسلم 2730 (حديث ابن عباس): «كان يقول عند الكرب...»", grade: "صحيح — متفق عليه", note: "", reward: "", count: 1, cat: "الكرب", quran: false),
        DuaItem(id: "du-12", text: "اللَّهُ اللَّهُ رَبِّي، لاَ أُشْرِكُ بِهِ شَيْئًا", ref: "أبو داود 1525", source: "أبو داود 1525 (حديث أسماء بنت عميس): «ألا أعلمك كلمات تقولينهن عند الكرب أو في الكرب»", grade: "صحيح — الألباني (صحيح أبي داود 1525، صحيح ابن ماجه 3146)؛ شعيب الأرناؤوط: إسناده صحيح (تخريج سنن أبي داود 1525). وقال الألباني في صحيح الجامع 2623: حسن", note: "", reward: "", count: 1, cat: "الكرب", quran: false),
        DuaItem(id: "du-13", text: "لاَ إِلَهَ إِلاَّ أَنْتَ، سُبْحَانَكَ، إِنِّي كُنْتُ مِنَ الظَّالِمِينَ", ref: "الترمذي 3505", source: "الترمذي 3505 (حديث سعد بن أبي وقاص): «دعوة ذي النون إذ دعا وهو في بطن الحوت: لا إله إلا أنت سبحانك إني كنت من الظالمين، فإنه لم يدع بها رجل مسلم في شيء قط إلا استجاب الله له»؛ وهي في القرآن (الأنبياء 87)", grade: "صحيح — الألباني (صحيح الترمذي 3505)", note: "اللفظ لفظ الحديث، وهو نص الآية 21:87 من «لا إله إلا أنت» (في المصحف: أَن لَّآ إِلَـٰهَ إِلَّآ أَنتَ سُبْحَـٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّـٰلِمِينَ).", reward: "«فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلاَّ اسْتَجَابَ اللَّهُ لَهُ» (الترمذي 3505)", count: 1, cat: "الكرب", quran: false),
        DuaItem(id: "du-14", text: "اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ، وَتَعْلَمُ وَلاَ أَعْلَمُ، وَأَنْتَ عَلاَّمُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاقْدُرْهُ لِي، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ رَضِّنِي بِهِ. وَيُسَمِّي حَاجَتَه", ref: "البخاري 6382", source: "البخاري 6382 و1162 (حديث جابر بن عبد الله): «كان يعلّمنا الاستخارة في الأمور كلها كالسورة من القرآن: إذا همّ بالأمر فليركع ركعتين ثم يقول... ويسمّي حاجته»", grade: "صحيح — رواه البخاري", note: "تُصلّى ركعتان من غير الفريضة ثم يدعو، ويسمّي حاجته مكان «هذا الأمر». ما بين الشرطتين «أو قال: عاجل أمري وآجله» شكٌّ من الراوي، وهو جزء من لفظ البخاري فأبقيناه كما هو.", reward: "", count: 1, cat: "الاستخارة", quran: false),
        DuaItem(id: "du-15", text: "لاَ بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ", ref: "البخاري 5656", source: "البخاري 5656 (حديث ابن عباس): «كان إذا دخل على مريض يعوده قال...»", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "عيادة المريض", quran: false),
        DuaItem(id: "du-16", text: "أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ", ref: "أبو داود 3106", source: "أبو داود 3106 (حديث ابن عباس): «من عاد مريضًا لم يحضر أجله فقال عنده سبع مرار: أسأل الله العظيم رب العرش العظيم أن يشفيك، إلا عافاه الله من ذلك المرض»", grade: "صحيح — الألباني (صحيح أبي داود 3106)؛ النووي: صحيح (الأذكار 180، خلاصة الأحكام 2/912)؛ شعيب الأرناؤوط: إسناده قوي على شرط البخاري (تخريج صحيح ابن حبان 2978)، وحسّنه ابن حجر", note: "", reward: "«إِلاَّ عَافَاهُ اللَّهُ مِنْ ذَلِكَ الْمَرَضِ» (أبو داود 3106)", count: 7, cat: "عيادة المريض", quran: false),
        DuaItem(id: "du-17", text: "بِاسْمِ اللَّهِ", ref: "مسلم 2202", source: "مسلم 2202 (حديث عثمان بن أبي العاص، شكا وجعًا في جسده): «ضع يدك على الذي تألّم من جسدك وقل: باسم الله ثلاثًا، وقل سبع مرات: أعوذ بالله وقدرته من شر ما أجد وأحاذر»", grade: "صحيح — رواه مسلم", note: "تضع يدك على موضع الألم، ثم تقول «بسم الله» ثلاثًا، ثم الذكر التالي سبعًا.", reward: "", count: 3, cat: "الألم في الجسد", quran: false),
        DuaItem(id: "du-18", text: "أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ", ref: "مسلم 2202", source: "مسلم 2202 (حديث عثمان بن أبي العاص)", grade: "صحيح — رواه مسلم", note: "", reward: "", count: 7, cat: "الألم في الجسد", quran: false),
        DuaItem(id: "du-19", text: "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا", ref: "مسلم 918", source: "مسلم 918 (حديث أم سلمة): «ما من مسلم تصيبه مصيبة فيقول ما أمره الله... إلا أخلف الله له خيرًا منها»", grade: "صحيح — رواه مسلم", note: "", reward: "«إِلاَّ أَخْلَفَ اللَّهُ لَهُ خَيْرًا مِنْهَا» (مسلم 918)", count: 1, cat: "المصيبة", quran: false),
        DuaItem(id: "du-20", text: "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ", ref: "مسلم 899", source: "مسلم 899 (حديث عائشة): «كان إذا عصفت الريح قال...»", grade: "صحيح — رواه مسلم", note: "", reward: "", count: 1, cat: "الريح", quran: false),
        DuaItem(id: "du-21", text: "صَيِّبًا نَافِعًا", ref: "البخاري 1032", source: "البخاري 1032 (حديث عائشة): «كان إذا رأى المطر قال...»", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "المطر", quran: false),
        DuaItem(id: "du-22", text: "مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ", ref: "البخاري 846", source: "البخاري 846، ومسلم 71 (حديث زيد بن خالد الجهني، حديث قدسي): «فأما من قال: مطرنا بفضل الله ورحمته، فذلك مؤمن بي وكافر بالكوكب»", grade: "صحيح — متفق عليه", note: "", reward: "", count: 1, cat: "بعد نزول المطر", quran: false),
        DuaItem(id: "du-23", text: "بِسْمِ اللَّهِ", ref: "البخاري 5376", source: "البخاري 5376، ومسلم 2022 (حديث عمر بن أبي سلمة): «يا غلام، سمِّ الله، وكل بيمينك، وكل مما يليك»", grade: "صحيح — متفق عليه", note: "التسمية قبل الأكل مأمور بها في الصحيحين بلفظ «سمِّ الله»، وصيغتها «بسم الله». أما «بسم الله في أوله وآخره» لمن نسي فمختلف في تصحيحها فلم نُدخلها.", reward: "", count: 1, cat: "الطعام", quran: false),
        DuaItem(id: "du-24", text: "الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلاَ مُوَدَّعٍ، وَلاَ مُسْتَغْنًى عَنْهُ رَبَّنَا", ref: "البخاري 5458", source: "البخاري 5458 (حديث أبي أمامة): «كان إذا رفع مائدته قال...»", grade: "صحيح — رواه البخاري", note: "يقال بعد الفراغ من الطعام.", reward: "", count: 1, cat: "الطعام", quran: false),
        DuaItem(id: "du-25", text: "الْحَمْدُ لِلَّهِ", ref: "البخاري 6224", source: "البخاري 6224 (حديث أبي هريرة): «إذا عطس أحدكم فليقل: الحمد لله، وليقل له أخوه أو صاحبه: يرحمك الله، فإذا قال له: يرحمك الله، فليقل: يهديكم الله ويصلح بالكم»", grade: "صحيح — رواه البخاري", note: "يقوله العاطس.", reward: "", count: 1, cat: "العطاس", quran: false),
        DuaItem(id: "du-26", text: "يَرْحَمُكَ اللَّهُ", ref: "البخاري 6224", source: "البخاري 6224 (حديث أبي هريرة)", grade: "صحيح — رواه البخاري", note: "يقوله من سمع العاطس يحمد الله.", reward: "", count: 1, cat: "العطاس", quran: false),
        DuaItem(id: "du-27", text: "يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ", ref: "البخاري 6224", source: "البخاري 6224 (حديث أبي هريرة)", grade: "صحيح — رواه البخاري", note: "يردّ به العاطس على من شمّته.", reward: "", count: 1, cat: "العطاس", quran: false),
        DuaItem(id: "du-28", text: "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", ref: "البخاري 6115", source: "البخاري 6115 و3282 (حديث سليمان بن صُرَد): «إني لأعلم كلمة لو قالها لذهب عنه ما يجد، لو قال: أعوذ بالله من الشيطان الرجيم»", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "الغضب", quran: false),
        DuaItem(id: "du-29", text: "بِسْمِ اللَّهِ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "عند وضع الرِّجل في الركاب (أول الركوب).", reward: "", count: 1, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-30", text: "الْحَمْدُ لِلَّهِ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "إذا استوى على ظهرها.", reward: "", count: 1, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-31", text: "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "وهو نص الآيتين 13-14 من سورة الزخرف، بلفظ الرواية.", reward: "", count: 1, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-32", text: "الْحَمْدُ لِلَّهِ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "", reward: "", count: 3, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-33", text: "اللَّهُ أَكْبَرُ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "", reward: "", count: 3, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-34", text: "سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ", ref: "أبو داود 2602", source: "أبو داود 2602، والترمذي 3446 (علي بن ربيعة: شهدت عليًّا أُتي بدابة ليركبها...، ثم ضحك وقال: «رأيت النبي ﷺ فعل كما فعلت»)", grade: "صحيح — الألباني (صحيح أبي داود 2602، صحيح الترمذي 3446)؛ النووي: إسناده صحيح (الأذكار 280)؛ الترمذي: حسن صحيح", note: "", reward: "", count: 1, cat: "الركوب (السيارة والدابة)", quran: false),
        DuaItem(id: "du-35", text: "اللَّهُ أَكْبَرُ", ref: "مسلم 1342", source: "مسلم 1342 (حديث ابن عمر): «كان إذا استوى على بعيره خارجًا إلى سفر كبّر ثلاثًا، ثم قال...»", grade: "صحيح — رواه مسلم", note: "يكبّر ثلاثًا إذا استوى على مركوبه خارجًا إلى سفر، ثم يقول دعاء السفر (البند التالي).", reward: "", count: 3, cat: "السفر", quran: false),
        DuaItem(id: "du-36", text: "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ", ref: "مسلم 1342", source: "مسلم 1342 (حديث ابن عمر) — دعاء السفر", grade: "صحيح — رواه مسلم", note: "", reward: "", count: 1, cat: "السفر", quran: false),
        DuaItem(id: "du-37", text: "آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ", ref: "مسلم 1342", source: "مسلم 1342 (حديث ابن عمر): «وإذا رجع قالهن وزاد فيهن: آيبون تائبون عابدون لربنا حامدون»", grade: "صحيح — رواه مسلم", note: "عند الرجوع يقول دعاء السفر نفسه ويزيد هذا في آخره.", reward: "", count: 1, cat: "الرجوع من السفر", quran: false),
        DuaItem(id: "du-38", text: "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", ref: "مسلم 2708", source: "مسلم 2708 (حديث خولة بنت حكيم): «من نزل منزلًا ثم قال... لم يضره شيء حتى يرتحل من منزله ذلك»", grade: "صحيح — رواه مسلم", note: "", reward: "«لَمْ يَضُرُّهُ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ» (مسلم 2708)", count: 1, cat: "نزول منزل", quran: false),
        DuaItem(id: "ph-1013", text: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ", ref: "أبو داود 5074", source: "سنن أبي داود ٥٠٧٤ (ابن عمر) — جزء من دعاء الصباح والمساء", grade: "صحيح — الألباني (صحيح أبي داود ٥٠٧٤)", note: "هذا مقطع من أول الدعاء الكامل الموجود في أذكار الصباح والمساء.", reward: "", count: 1, cat: "أدعية جامعة", quran: false),
        DuaItem(id: "ph-1019", text: "رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي", ref: "أبو داود 874", source: "سنن أبي داود ٨٧٤ (حذيفة)", grade: "صحيح — الألباني (صحيح أبي داود ٨٧٤، إرواء الغليل ٣٣٥)؛ ابن باز: ثابت؛ الوادعي: صحيح على شرط الشيخين؛ شعيب: إسناده صحيح", note: "يقال بين السجدتين.", reward: "", count: 1, cat: "بين السجدتين", quran: false),
        DuaItem(id: "ph-1021", text: "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبادَتِكَ", ref: "أبو داود 1522", source: "سنن أبي داود ١٥٢٢، والنسائي (معاذ بن جبل)", grade: "صحيح — الألباني (صحيح أبي داود ١٥٢٢)؛ النووي وشعيب وابن باز: إسناده صحيح؛ ابن حجر: إسناده قوي", note: "يقال دبر كل صلاة.", reward: "", count: 1, cat: "أدعية جامعة", quran: false),
        DuaItem(id: "ph-1022", text: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ", ref: "أبو داود 792", source: "سنن أبي داود ٧٩٢", grade: "صحيح — الألباني (صحيح أبي داود ٧٩٢)؛ شعيب: إسناده صحيح؛ ابن حجر: صحيح؛ الوادعي: صحيح على شرط الشيخين", note: "", reward: "", count: 1, cat: "أدعية جامعة", quran: false),
        DuaItem(id: "ph-1026", text: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", ref: "البخاري 6369", source: "صحيح البخاري ٦٣٦٩ و٦٣٦٣ (أنس بن مالك)", grade: "صحيح — رواه البخاري", note: "", reward: "", count: 1, cat: "أدعية جامعة", quran: false),
        DuaItem(id: "ph-1030", text: "اللَّهُمَّ لاَ طَيْرَ إِلاَّ طَيْرُكَ، وَلاَ خَيْرَ إِلاَّ خَيْرُكَ، وَلاَ إِلَهَ غَيْرُكَ", ref: "أحمد 7045", source: "مسند أحمد ٧٠٤٥ (عبد الله بن عمرو)", grade: "الألباني: إسناده صحيح (السلسلة الصحيحة ٣/٥٤)؛ أحمد شاكر: إسناده صحيح؛ شعيب الأرناؤوط: حسن (تخريج المسند ٧٠٤٥)", note: "", reward: "", count: 1, cat: "أدعية جامعة", quran: false),
        DuaItem(id: "ph-1031", text: "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ", ref: "أبو داود 5045", source: "سنن أبي داود ٥٠٤٥ (حفصة)، والترمذي ٣٣٩٨ (البراء)", grade: "صحيح دون قوله «ثلاث مرار» — الألباني (صحيح أبي داود ٥٠٤٥)؛ الترمذي: حسن صحيح؛ ابن حجر: حسن", note: "يقال عند النوم. والنص هنا بلا «ثلاث مرار».", reward: "", count: 1, cat: "أدعية جامعة", quran: false)
    ]
